  // AI-generated END - 构建方法

  // AI-generated START - 构建头像区域
  Widget _buildAvatarSection(BuildContext context, MPAddExportProvider provider) {
    return Stack(
      alignment: Alignment.center,
      children: [
        // 主头像圆形
        GestureDetector(
          onTap: () => _pickImage(context, provider),
          child: SizedBox(
            width: 96.0,
